const input = $input.first().json;
const output = input.output ?? input.text;
if (typeof output !== 'string' || !output.trim()) throw new Error('Expected the agent reply in output or text.');
const spokenText = output
  .replace(/\[([^\]]+)\]\([^)]+\)/g, '$1')
  .replace(/^\s{0,3}#{1,6}\s+/gm, '')
  .replace(/[*_\x60]/g, '')
  .replace(/^\s*[-+]\s+/gm, '')
  .trim();
return [{json: {
  output,
  request: {
    model: 'gemini-3.8-flash-tts',
    input: [{type: 'user_input', content: [{
      type: 'text', text: spokenText,
      annotations: [{type: 'speech_metadata', style: 'Speak in French as spoken in France. Warm, reassuring, natural conversational delivery. Clear articulation, a relaxed moderate pace, and short natural pauses between ideas. Avoid a theatrical or advertising tone. Read the transcript faithfully without adding words.'}]
    }]}],
    response_format: {type: 'audio', mime_type: 'audio/wav', sample_rate: 24000},
    generation_config: {speech_config: [{voice: 'Sulafat'}]}
  }
}}];

const output = $('Dyseurope - Prepare speech').first().json.output;
const response = $input.first().json;
const parts = (Array.isArray(response.steps) ? response.steps : [])
  .filter(step => step.type === 'model_output')
  .flatMap(step => Array.isArray(step.content) ? step.content : []);
const audio = parts.filter(part => part.type === 'audio' && typeof part.data === 'string').at(-1);
if (!audio || audio.data.length > 16000000 || !/^[A-Za-z0-9+/]+={0,2}$/.test(audio.data)) {
  return [{json: {output, audio: null}}];
}
const wav = Buffer.from(audio.data, 'base64');
if (wav.length < 44 || wav.toString('ascii', 0, 4) !== 'RIFF' || wav.toString('ascii', 8, 12) !== 'WAVE') {
  return [{json: {output, audio: null}}];
}
return [{json: {output, audio: {mimeType: 'audio/wav', data: audio.data}}}];
